import os
exec(open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'lesson_video.py'), encoding='utf-8').read())
AR = str.maketrans('0123456789', '٠١٢٣٤٥٦٧٨٩')
def ar(n): return str(n).translate(AR)
def P(b, x=None): return f'<span class="b">{ar(b)}' + (f'<sup>{ar(x)}</sup>' if x else '') + '</span>'
def ng(v): return f'<span class="ngv"><i>−</i>{ar(v)}</span>'
def PN(v, x): return f'<span class="b"><span class="brv">({ng(v)})</span><sup>{ar(x)}</sup></span>'
def PM(v): return f'<span class="ngv"><i>±</i>{ar(v)}</span>'
def R(v, k=2):
    idx = f'<i class="ri">{ar(k)}</i>' if k == 3 else ''
    return (f'<span class="rt">{idx}<svg class="rsv" viewBox="0 0 32 64" preserveAspectRatio="none"><path d="M31 38 L25 34 L15 62 L1 1.5"/></svg>'
            f'<span class="ov">{ar(v)}</span></span>')
def rep(b, n): return f' {X} '.join(ar(b) for _ in range(n))
def K(t): return f'<b style="color: #C2410C">{t}</b>'
